/* From Uiverse.io by G4b413l - Tags: card, animated */
.__UIV_SCOPE__ .container {
  display: flex;
  gap: 10px;
}

.__UIV_SCOPE__ .card {
  background-color: #fff;
  height: 100px;
  width: 100px;
  flex: 1;
  border-radius: 16px;
  transition: all 0.3s ease;
  display: flex;
  align-items: center;
  justify-content: center;
}

.__UIV_SCOPE__ .card:hover {
  flex: 2;
  background-color: #b8b8b8;
}
